package com.bank.comm.sync;

import java.math.BigDecimal;
import java.util.logging.Logger;

// SYNCHRONOUS: the caller BLOCKS and needs the answer now (funds check + debit).
// In Spring this is a @FeignClient or a RestClient call.
public class AccountClient {
    private static final Logger log = Logger.getLogger(AccountClient.class.getName());
    private BigDecimal balance = new BigDecimal("1000000");

    public boolean hasFunds(String accountId, BigDecimal amount) {
        boolean ok = balance.compareTo(amount) >= 0;
        log.info(() -> "SYNC funds check " + accountId + " for " + amount + " → " + ok);
        return ok;   // caller waits for this
    }
    public void debit(String accountId, BigDecimal amount) {
        balance = balance.subtract(amount);
        log.info(() -> "SYNC debit " + amount + " from " + accountId + " → " + balance);
    }
}
