package com.bank.comm.async;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.logging.Logger;

// ASYNCHRONOUS: a Kafka-style broker. Publish and return immediately.
public class EventBus {
    private static final Logger log = Logger.getLogger(EventBus.class.getName());
    private final List<Consumer<String>> subscribers = new ArrayList<>();

    public void subscribe(Consumer<String> consumer) { subscribers.add(consumer); }

    public void publish(String topic, String event) {
        log.info(() -> "ASYNC publish to '" + topic + "': " + event + " (sender does NOT wait)");
        // consumers process later / independently
        for (Consumer<String> c : subscribers) c.accept(event);
    }
}
