package com.bank.comm.payment;

import com.bank.comm.async.EventBus;
import com.bank.comm.sync.AccountClient;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Uses BOTH styles: synchronous where it needs the answer now,
// asynchronous for everything that can happen later.
public class PaymentService {
    private static final Logger log = Logger.getLogger(PaymentService.class.getName());
    private final AccountClient accountClient;   // sync dependency
    private final EventBus eventBus;             // async dependency

    public PaymentService(AccountClient accountClient, EventBus eventBus) {
            this.accountClient = accountClient;
            this.eventBus = eventBus;
    }

    public String transfer(String from, String to, BigDecimal amount) {
        // SYNC: must know NOW whether funds are sufficient
        if (!accountClient.hasFunds(from, amount)) return "REJECTED_INSUFFICIENT_FUNDS";
        accountClient.debit(from, amount);        // SYNC: need confirmed debit
        log.info(() -> "Transfer COMPLETED, responding to customer immediately");
        // ASYNC: notification + audit + fraud happen later, customer does not wait
        eventBus.publish("payment-events",
            "PAYMENT_COMPLETED from=" + from + " to=" + to + " amount=" + amount);
        return "COMPLETED";
    }
}
