package com.bank.comm;

import com.bank.comm.async.AuditConsumer;
import com.bank.comm.async.EventBus;
import com.bank.comm.async.NotificationConsumer;
import com.bank.comm.payment.PaymentService;
import com.bank.comm.sync.AccountClient;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class CommDemo {
    private static final Logger log = Logger.getLogger(CommDemo.class.getName());

    public static void main(String[] args) {
        EventBus eventBus = new EventBus();
        NotificationConsumer notify = new NotificationConsumer();
        AuditConsumer audit = new AuditConsumer();
        eventBus.subscribe(notify::onPaymentEvent);   // independent async consumers
        eventBus.subscribe(audit::onPaymentEvent);

        PaymentService payment = new PaymentService(new AccountClient(), eventBus);
        BigDecimal rentAmount = new BigDecimal("50000");

        log.info("=== Transfer: SYNC check + debit, then ASYNC events ===");
        String result = payment.transfer("SAV2001", "CUR3001", rentAmount);
        log.info("Customer response: " + result);
    }
}
